-- Complete schema for a fresh installation. Normal upgrades use bin/setup.php.
CREATE TABLE IF NOT EXISTS settings(name VARCHAR(100) PRIMARY KEY,value JSON NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS staff_users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role VARCHAR(40) NOT NULL,permissions JSON NOT NULL,enabled BOOLEAN NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS customers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(50) NOT NULL DEFAULT '',password VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS customer_addresses(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NOT NULL,label VARCHAR(100) NOT NULL,address TEXT NOT NULL,FOREIGN KEY(customer_id) REFERENCES customers(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rate_limits(id VARCHAR(64) PRIMARY KEY,attempts INT NOT NULL DEFAULT 0,expires_at DATETIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS password_resets(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,used_at DATETIME NULL,FOREIGN KEY(customer_id) REFERENCES customers(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,parent_id BIGINT UNSIGNED NULL,name VARCHAR(150) NOT NULL,slug VARCHAR(190) NOT NULL UNIQUE,description TEXT,image VARCHAR(255) NOT NULL DEFAULT '',sort_order INT NOT NULL DEFAULT 0,enabled BOOLEAN DEFAULT 1,seo_title VARCHAR(190) DEFAULT '',seo_description TEXT,FOREIGN KEY(parent_id) REFERENCES categories(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS brands(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL UNIQUE,logo VARCHAR(255) DEFAULT '',description TEXT,sort_order INT DEFAULT 0,enabled BOOLEAN DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS suppliers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,contact_person VARCHAR(150) DEFAULT '',phone VARCHAR(50) DEFAULT '',email VARCHAR(190) DEFAULT '',address TEXT,notes TEXT,enabled BOOLEAN DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS attributes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,type VARCHAR(30) NOT NULL,unit VARCHAR(50) DEFAULT '',required BOOLEAN DEFAULT 0,visible BOOLEAN DEFAULT 1,filterable BOOLEAN DEFAULT 0,variant BOOLEAN DEFAULT 0,sort_order INT DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS attribute_options(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,attribute_id BIGINT UNSIGNED NOT NULL,label VARCHAR(150) NOT NULL,color VARCHAR(10) DEFAULT '',UNIQUE(attribute_id,label),FOREIGN KEY(attribute_id) REFERENCES attributes(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS category_attributes(category_id BIGINT UNSIGNED NOT NULL,attribute_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(category_id,attribute_id),FOREIGN KEY(category_id) REFERENCES categories(id),FOREIGN KEY(attribute_id) REFERENCES attributes(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,slug VARCHAR(190) NOT NULL UNIQUE,sku VARCHAR(100) NOT NULL UNIQUE,barcode VARCHAR(100) DEFAULT '',category_id BIGINT UNSIGNED NOT NULL,brand_id BIGINT UNSIGNED NULL,supplier_id BIGINT UNSIGNED NULL,short_description TEXT,description TEXT,unit VARCHAR(30) DEFAULT 'piece',condition_type VARCHAR(10) DEFAULT 'new',status VARCHAR(20) DEFAULT 'draft',featured BOOLEAN DEFAULT 0,new_arrival BOOLEAN DEFAULT 0,deal BOOLEAN DEFAULT 0,has_variants BOOLEAN DEFAULT 0,warranty TEXT,tags TEXT,seo_title VARCHAR(190) DEFAULT '',seo_description TEXT,views BIGINT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id),FOREIGN KEY(brand_id) REFERENCES brands(id),FOREIGN KEY(supplier_id) REFERENCES suppliers(id),INDEX(status,category_id),INDEX(brand_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS product_variants(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,sku VARCHAR(100) NOT NULL UNIQUE,barcode VARCHAR(100) DEFAULT '',label VARCHAR(190) DEFAULT 'Standard',combination VARCHAR(255) NOT NULL DEFAULT '',price BIGINT NOT NULL,sale_price BIGINT NULL,cost BIGINT NOT NULL DEFAULT 0,image VARCHAR(255) DEFAULT '',enabled BOOLEAN DEFAULT 1,track_stock BOOLEAN DEFAULT 1,low_stock INT DEFAULT 3,availability VARCHAR(15) DEFAULT 'normal',expected_date DATE NULL,max_preorder INT NULL,deposit_type VARCHAR(15) DEFAULT 'none',deposit_value BIGINT DEFAULT 0,UNIQUE(product_id,combination),FOREIGN KEY(product_id) REFERENCES products(id),CHECK(price>=0),CHECK(sale_price IS NULL OR (sale_price>=0 AND sale_price<=price)),CHECK(cost>=0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS variant_attribute_values(variant_id BIGINT UNSIGNED NOT NULL,attribute_id BIGINT UNSIGNED NOT NULL,option_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(variant_id,attribute_id),FOREIGN KEY(variant_id) REFERENCES product_variants(id),FOREIGN KEY(attribute_id) REFERENCES attributes(id),FOREIGN KEY(option_id) REFERENCES attribute_options(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS product_attribute_values(product_id BIGINT UNSIGNED NOT NULL,attribute_id BIGINT UNSIGNED NOT NULL,value TEXT NOT NULL,PRIMARY KEY(product_id,attribute_id),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(attribute_id) REFERENCES attributes(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS product_images(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,path VARCHAR(255) NOT NULL,alt VARCHAR(190) DEFAULT '',sort_order INT DEFAULT 0,FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS inventory_balances(variant_id BIGINT UNSIGNED PRIMARY KEY,physical INT NOT NULL DEFAULT 0,reserved INT NOT NULL DEFAULT 0,FOREIGN KEY(variant_id) REFERENCES product_variants(id),CHECK(physical>=0),CHECK(reserved>=0),CHECK(physical>=reserved)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,number VARCHAR(40) NULL UNIQUE,checkout_key VARCHAR(100) NOT NULL UNIQUE,request_hash CHAR(64) NOT NULL,access_hash CHAR(64) NOT NULL,customer_id BIGINT UNSIGNED NULL,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(50) NOT NULL,billing_address TEXT NOT NULL,shipping_address TEXT NOT NULL,delivery VARCHAR(30) NOT NULL,zone VARCHAR(100) DEFAULT '',notes TEXT,status VARCHAR(30) DEFAULT 'pending',currency VARCHAR(10) NOT NULL,subtotal BIGINT NOT NULL,discount BIGINT NOT NULL,tax BIGINT NOT NULL,shipping BIGINT NOT NULL,total BIGINT NOT NULL,due_now BIGINT NOT NULL,store_snapshot JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id),INDEX(status,created_at),INDEX(customer_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,variant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(190) NOT NULL,sku VARCHAR(100) NOT NULL,variant_label VARCHAR(190) NOT NULL,category_name VARCHAR(150) NOT NULL,brand_name VARCHAR(150) DEFAULT '',quantity INT NOT NULL,unit_price BIGINT NOT NULL,unit_cost BIGINT NOT NULL,discount BIGINT NOT NULL,tax BIGINT NOT NULL,total BIGINT NOT NULL,due_now BIGINT NOT NULL,availability VARCHAR(15) NOT NULL,deposit_type VARCHAR(15) NOT NULL,deposit_value BIGINT NOT NULL,expected_date DATE NULL,progress VARCHAR(40) DEFAULT 'awaiting confirmation',restocked INT NOT NULL DEFAULT 0,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(variant_id) REFERENCES product_variants(id),INDEX(variant_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS inventory_reservations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_item_id BIGINT UNSIGNED NOT NULL UNIQUE,variant_id BIGINT UNSIGNED NOT NULL,quantity INT NOT NULL,state VARCHAR(20) NOT NULL DEFAULT 'reserved',expires_at DATETIME NULL,FOREIGN KEY(order_item_id) REFERENCES order_items(id),FOREIGN KEY(variant_id) REFERENCES product_variants(id),INDEX(state,expires_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS inventory_movements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,variant_id BIGINT UNSIGNED NOT NULL,quantity INT NOT NULL,type VARCHAR(30) NOT NULL,order_id BIGINT UNSIGNED NULL,purchase_id BIGINT UNSIGNED NULL,staff_id BIGINT UNSIGNED NULL,reason TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(variant_id) REFERENCES product_variants(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_status_history(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,item_id BIGINT UNSIGNED NULL,status VARCHAR(40) NOT NULL,notes TEXT,staff_id BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,idempotency_key VARCHAR(100) NOT NULL UNIQUE,amount BIGINT NOT NULL,currency VARCHAR(10) NOT NULL,method VARCHAR(30) NOT NULL,reference VARCHAR(190) DEFAULT '',notes TEXT,status VARCHAR(20) DEFAULT 'pending',proof VARCHAR(255) NULL,recorded_by BIGINT UNSIGNED NULL,verified_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,verified_at DATETIME NULL,FOREIGN KEY(order_id) REFERENCES orders(id),CHECK(amount>0),INDEX(order_id,status),INDEX(created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payment_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,payment_id BIGINT UNSIGNED NOT NULL,event VARCHAR(30) NOT NULL,staff_id BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(payment_id) REFERENCES payments(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS refunds(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,idempotency_key VARCHAR(100) NOT NULL UNIQUE,amount BIGINT NOT NULL,merchandise_amount BIGINT NOT NULL,cost_reversal BIGINT NOT NULL DEFAULT 0,reason TEXT NOT NULL,reference VARCHAR(190) NOT NULL,staff_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id),CHECK(amount>0),CHECK(merchandise_amount>=0 AND merchandise_amount<=amount)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS invoices(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL UNIQUE,number VARCHAR(40) NULL UNIQUE,snapshot JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS purchase_receipts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,supplier_id BIGINT UNSIGNED NOT NULL,reference VARCHAR(190) NOT NULL,notes TEXT,status VARCHAR(20) DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,received_at DATETIME NULL,FOREIGN KEY(supplier_id) REFERENCES suppliers(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS purchase_receipt_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,purchase_id BIGINT UNSIGNED NOT NULL,variant_id BIGINT UNSIGNED NOT NULL,quantity INT NOT NULL,unit_cost BIGINT NOT NULL,FOREIGN KEY(purchase_id) REFERENCES purchase_receipts(id),FOREIGN KEY(variant_id) REFERENCES product_variants(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reviews(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,rating INT NOT NULL,text TEXT NOT NULL,status VARCHAR(20) DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(customer_id,product_id),FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(product_id) REFERENCES products(id),CHECK(rating BETWEEN 1 AND 5)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS wishlists(customer_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(customer_id,product_id),FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS coupons(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(50) NOT NULL UNIQUE,type VARCHAR(15) NOT NULL,value BIGINT NOT NULL,minimum BIGINT DEFAULT 0,starts_at DATE NOT NULL,ends_at DATE NOT NULL,usage_limit INT NULL,product_id BIGINT UNSIGNED NULL,category_id BIGINT UNSIGNED NULL,enabled BOOLEAN DEFAULT 1,FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(category_id) REFERENCES categories(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS coupon_redemptions(coupon_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NOT NULL UNIQUE,PRIMARY KEY(coupon_id,order_id),FOREIGN KEY(coupon_id) REFERENCES coupons(id),FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS hero_slides(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,heading VARCHAR(190) NOT NULL,description TEXT,image VARCHAR(255) NOT NULL,mobile_image VARCHAR(255) DEFAULT '',primary_label VARCHAR(100) NOT NULL,primary_url VARCHAR(255) NOT NULL,secondary_label VARCHAR(100) DEFAULT '',secondary_url VARCHAR(255) DEFAULT '',sort_order INT DEFAULT 0,enabled BOOLEAN DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS homepage_sections(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(190) NOT NULL,type VARCHAR(30) NOT NULL,selection JSON NOT NULL,item_limit INT DEFAULT 6,sort_order INT DEFAULT 0,enabled BOOLEAN DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS content_blocks(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,type VARCHAR(20) NOT NULL,title VARCHAR(190) NOT NULL,body TEXT,image VARCHAR(255) DEFAULT '',link VARCHAR(255) DEFAULT '',sort_order INT DEFAULT 0,enabled BOOLEAN DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,slug VARCHAR(100) NOT NULL UNIQUE,title VARCHAR(190) NOT NULL,body TEXT NOT NULL,enabled BOOLEAN DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,staff_id BIGINT UNSIGNED NULL,action VARCHAR(80) NOT NULL,entity VARCHAR(80) NOT NULL,entity_id BIGINT UNSIGNED NOT NULL,data JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;

ALTER TABLE order_items ADD COLUMN stock_tracked BOOLEAN NOT NULL DEFAULT 1;
ALTER TABLE orders ADD COLUMN refund_state VARCHAR(20) NOT NULL DEFAULT 'none';
CREATE INDEX idx_attribute_filter ON product_attribute_values(attribute_id,value(100));
CREATE INDEX idx_variant_option_filter ON variant_attribute_values(attribute_id,option_id);

ALTER TABLE orders ADD COLUMN internal_notes TEXT NULL;

CREATE TABLE IF NOT EXISTS migrations(version VARCHAR(100) PRIMARY KEY, applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
INSERT IGNORE INTO migrations(version) VALUES ('001_initial.sql'),('002_inventory_snapshots.sql'),('003_order_notes.sql');
